import React, { useState } from 'react';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css'; // Default styles
import '../Style/TaskCalendar.css'
function TaskCalendar() {
  const [date, setDate] = useState(new Date());
 const day = date.toLocaleString('en-US',{ timeZone: "Asia/Karachi" }, { weekday: 'long' }); // e.g., "Sunday"
  const dates = date.toLocaleDateString('en-US',{ timeZone: "Asia/Karachi" }, {
    day: '2-digit',
    month: 'long',
    year: 'numeric'
  }); 
  return (
    <div>
      <h2 className='DisplayDate'>{new Date().toDateString()}</h2>
      <Calendar
        onChange={setDate}
        value={date}
        tileClassName={({ date, view }) => {
          // Example: highlight today
          if (date.toDateString() === new Date().toDateString()) {
            return 'highlight';
          }
        }}
      />
    </div>
  );
}

export default TaskCalendar;
